-- Ejecutar en la base PostgreSQL creada en Neon.
-- Neon ya crea la base al provisionar el proyecto; no ejecutar CREATE DATABASE aquí.

CREATE TABLE "Categorias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Nombre" varchar(60) NOT NULL,
    "Descripcion" varchar(250),
    CONSTRAINT "UQ_Categorias_Nombre" UNIQUE ("Nombre")
);

CREATE TABLE "Eventos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Titulo" varchar(120) NOT NULL,
    "Lugar" varchar(150) NOT NULL,
    "Fecha" timestamp with time zone NOT NULL,
    "Aforo" integer NOT NULL,
    "Precio" numeric(18,2) NOT NULL,
    "CategoriaId" integer NOT NULL,
    CONSTRAINT "FK_Eventos_Categorias" FOREIGN KEY ("CategoriaId") REFERENCES "Categorias"("Id"),
    CONSTRAINT "CK_Eventos_Aforo" CHECK ("Aforo" BETWEEN 1 AND 50000),
    CONSTRAINT "CK_Eventos_Precio" CHECK ("Precio" >= 0)
);

CREATE UNIQUE INDEX "UX_Eventos_Titulo_Fecha" ON "Eventos" ("Titulo", "Fecha");

